        const isDisabled = isRpn && btn.disabledInRpn;

        const handleClick = () => {
          if (isDisabled) return;
          if (btn.value === 'clear') {
            onClear();
          } else if (btn.value === 'backspace') {
            onBackspace();
          } else if (btn.value === 'equals') {
            onEvaluate();
          } else {
            onKeyPress(btn.value);
          }
        };

        return (
          <button
            key={index}
