+        const tokens = item.expression.split(' ');
+        const numericalTokens = tokens.filter(tok => !isNaN(parseFloat(tok)) || tok === 'pi' || tok === 'e');
+        setStack((prev) => [...prev, ...numericalTokens]);
+      }
+    } else {
+      if (part === 'expression') {
